data.query:
query Shift($workcenterId: String!){
  	workcenter(
      where:{
        id: {_eq: $workcenterId}
      }
    ){
    edges{
      node{
        id
        shiftGroup{
          shifts{
            edges {
              node {
                id
                name
                startHour
                startMinute
                endHour
                endMinute
                creditAtStart
                timeZone

                monday
                tuesday
                wednesday
                thursday
                friday
                saturday
                sunday
              }
            }
          }
        }
      }
    }
  }

  setting(
    where:{
      id: {_eq: "TimeZone"}
    }
  ){
    edges{
    node{
    defaultValue
  }
  }
  }

}

query (
  $workcenterId: String!,
  $shiftId: String!,
  $startAt: DateTime,
  $endTime: DateTime
){
  oee(
    where:{
      workcenterId:{ _eq: $workcenterId}
      shiftId:{ _eq: $shiftId}
      startAt:{ _gte: $startAt}
      endAt:{ _lte: $endTime}
    }
    orderBy:{field: shiftHour, direction: asc}
  ){
    edges{
      node{
        shiftHour
        totalProductionQuantity
        totalScrapQuantity
        oee
        availability
        performance
        quality
        plannedDowntime
        unplannedDowntime
        productionTime
        startAt
        endAt
        shift{
          id
          name
        }
      }
    }
  }

  workcenterHistory(
    where:{ 
      _or:[
        {
          _and:[
            { occurAt:{_gte: $startAt} }
            { occurAt:{_lt: $endTime} }
            { workcenterId:{ _eq: $workcenterId}}
          ]
        },
        {
          _and:[
            { endAt:{_gte: $startAt} }
            { endAt:{_lt: $endTime} }
            { workcenterId:{ _eq: $workcenterId}}
          ]
        },
        { 
          endAt: { _isNull: true },
          occurAt: {_lt: $endTime},
          workcenterId:{ _eq: $workcenterId}
        }
      ]
    }
    first: null
  ) {
    edges {
      node {
        id
        occurAt
        endAt
        duration
        transactionTypeId
        workcenterId
        mode{
            id
            name
            modeType{
              name
            }            
          }

      }
    }
  }

  modeType{
    edges{
      node{
        name
      }
    }
  }

  workcenter( 
    where:{
      id : { _eq: $workcenterId}
    }
  ){
    edges{
      node{ shiftGroupId }
    }
  }
}

data.transform:
(
  $timePayload := function($hour, $minute){{
    "hour": $hour,
    "minute": 0
  }};
  $end := $timePayload(shift.endHour, shift.endMinute);
  $start := $timePayload(shift.startHour, shift.startMinute);
  $timezone := timezone;

  {
    "workcenterId": workcenterId,
    "shiftId": shift.id,
    "startAt": $moment(creditAt).tz($timezone).set($start).format(),
    "endTime": $moment(creditAt).tz($timezone).set($end).format()
  }

)

